<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'; import { api, type Selection, type Valuation, type Row } from '../api'; import { origins, methods, valueBody } from '../utils'; import AssetSelect from '../components/AssetSelect.vue'; import AsyncPanel from '../components/AsyncPanel.vue'; import ValueResult from '../components/ValueResult.vue'; import JsonDetails from '../components/JsonDetails.vue'
const selection=ref<Selection>({asset_id:'',version:''}),tasks=ref<Row[]>([]),economics=ref<Row[]>([]),task=ref(''),economy=ref('fp1_fn5'),origin=ref('local_operational'),method=ref('decay30'),at=ref(''),report=ref<Valuation|null>(null),loading=ref(false),error=ref('')
onMounted(async()=>{try{const r=await api.tasks();tasks.value=r.tasks??[];economics.value=r.economics??[];task.value=tasks.value.find(t=>t.task_id==='random_seed101_d01500_logistic')?.task_id??tasks.value[0]?.task_id??''}catch(e){error.value=(e as Error).message}})
async function assess(){loading.value=true;error.value='';report.value=null;try{report.value=await api.value(valueBody(selection.value,task.value,economy.value,at.value,origin.value,method.value))}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
watch([selection,task,economy,origin,method,at],()=>{report.value=null},{deep:true})
</script>
<template><section class="panel"><p class="eyebrow">EXACT TASK UTILITY × DELIVERY RELIABILITY</p><h2>定义买方场景</h2><AssetSelect v-model="selection"/><div class="form-grid"><label>已有买方任务<select v-model="task" aria-label="买方任务"><option v-for="t in tasks" :key="t.task_id" :value="t.task_id">{{ t.task_id }}</option></select></label><label>假设经济场景<select v-model="economy" aria-label="经济场景"><option v-for="e in economics" :key="e.economics_id??e.id" :value="e.economics_id??e.id">{{ e.economics_id??e.id }} · {{ e.name??'假设损失单位' }}</option></select></label><label>信用来源<select v-model="origin" aria-label="价值信用来源"><option v-for="o in origins" :key="o.value" :value="o.value" :disabled="o.value==='simulated'">{{ o.label }}{{ o.value==='simulated'?'（仅用于模拟统计，当前估值不支持）':'' }}</option></select></label><label>信用模型<select v-model="method" aria-label="价值信用模型"><option v-for="m in methods" :key="m.value" :value="m.value">{{ m.label }}</option></select></label><label>评估时点（本地时间）<input v-model="at" type="datetime-local" aria-label="价值评估时点"></label></div><div class="formula">W = q × B_success + (1 − q) × B_failure − C_fixed</div><div class="actions"><button class="button" :disabled="loading||!task||!selection.asset_id" @click="assess">生成条件价值研究报告</button><span class="muted small">在线复用冻结的 validation 任务测量；不重新训练模型。</span></div></section><div class="notice">W 不是法定资产价格；Log Loss 改善不等于实际企业利润。q 是未来合同履约概率，不能当作已完成交付的成功概率。模型不重复乘以质量分。</div><AsyncPanel :loading="loading" :error="error" @retry="assess"><ValueResult v-if="report" :report="report"/><section v-else class="panel empty-intro"><span>⌁</span><h3>价值属于具体任务和条件</h3><p>只有资产 ID、版本、内容哈希、任务与经济假设精确匹配时才生成估值。</p></section></AsyncPanel><JsonDetails v-if="economics.length" :data="economics" title="查看经济场景的真实参数与假设"/></template>
